const targets=new Map(PORTRAIT_DELIVERY_ALIASES.map(({path,target})=>[path,target]));
/** Only bare/./ exact approved paths; preserve suffix byte-for-byte. No URL normalization. */
export function resolvePortraitDeliveryURL(url){
 if(typeof url!=='string')return url;
 const prefix=url.startsWith('./')?'./':'',body=url.slice(prefix.length),cut=body.search(/[?#]/),path=cut<0?body:body.slice(0,cut),suffix=cut<0?'':body.slice(cut);
 const target=targets.get(path);return target===undefined?url:prefix+target+suffix;
}
